/* deb_embedded.h - .deb files baked into the kernel image.
 *
 * Generated by tools/embed_deb.py from .deb files in OSC/debs/
 * (same idea as fse_embedded.h for .fse apps). The checked-in
 * version below is the empty table: no .deb is baked in until
 * someone runs the generator. deb_install_embedded() in deb.c
 * installs whatever this table lists, the first time a `deb`
 * command runs in the terminal.
 */
#ifndef FISIX_DEB_EMBEDDED_H
#define FISIX_DEB_EMBEDDED_H
#include <stdint.h>
/* Returns 1 and sets the data pointer and length for embedded .deb number idx
 * (0-based), or 0 when idx is past the end of the table. */
int deb_embedded_find(int idx, const uint8_t **data, uint32_t *len);
#endif
